-- เพิ่ม privacy_policy ใน settings table
INSERT INTO public.settings (key, value, updated_at, updated_by)
VALUES (
  'privacy_policy',
  '[{"icon":"🏢","title":"ผู้ควบคุมข้อมูลส่วนบุคคล","body":"การไฟฟ้าส่วนภูมิภาค (PEA) ระบบ PEA Meter & TR Mapping ใช้สำหรับงานภายในองค์กรเท่านั้น"},{"icon":"📋","title":"ข้อมูลที่เก็บรวบรวม","body":"ตำแหน่ง GPS ที่ใช้แก้ไขพิกัด, ภาพถ่ายที่แนบกับ Meter/TR, ประวัติการค้นหา (เก็บใน device), บันทึกการใช้งานระบบ (ชื่อผู้ใช้, การกระทำ, เวลา)"},{"icon":"🎯","title":"วัตถุประสงค์การใช้ข้อมูล","body":"เพื่อปรับปรุงความถูกต้องของพิกัดมิเตอร์และหม้อแปลงในระบบ GIS และเพื่อการตรวจสอบการใช้งานระบบ (Audit)"},{"icon":"🔒","title":"การเปิดเผยข้อมูล","body":"ข้อมูลไม่ถูกเปิดเผยแก่บุคคลภายนอก เข้าถึงได้เฉพาะพนักงาน PEA ที่ได้รับอนุญาตและมีบัญชีผู้ใช้ในระบบเท่านั้น"},{"icon":"⏱","title":"ระยะเวลาเก็บรักษาข้อมูล","body":"ข้อมูลการใช้งาน (Audit Log) เก็บไว้ตราบเท่าที่จำเป็นสำหรับการตรวจสอบ ภาพถ่ายเก็บใน device ของผู้ใช้ ไม่ได้ส่งขึ้น Server"},{"icon":"✅","title":"สิทธิ์ของเจ้าของข้อมูล (PDPA)","body":"ท่านมีสิทธิ์: ขอเข้าถึงข้อมูล, ขอแก้ไขข้อมูล, ขอลบข้อมูล, ขอจำกัดการประมวลผล โดยติดต่อผ่าน Admin ของระบบ"},{"icon":"📞","title":"ติดต่อ","body":"หากมีข้อสงสัยเกี่ยวกับนโยบายความเป็นส่วนตัว กรุณาติดต่อผู้ดูแลระบบ (Admin) ผ่านช่องทางภายในองค์กร"}]',
  NOW(),
  'system'
)
ON CONFLICT (key) DO UPDATE SET value = EXCLUDED.value, updated_at = NOW();
